\documentclass[11pt]{amsart}

\usepackage{amsmath,amssymb,amsthm}
\usepackage[margin=1in]{geometry}
\usepackage{hyperref}

\theoremstyle{plain}
\newtheorem{theorem}{Theorem}[section]
\newtheorem{lemma}[theorem]{Lemma}
\newtheorem{corollary}[theorem]{Corollary}
\theoremstyle{definition}
\newtheorem{definition}[theorem]{Definition}
\newtheorem{remark}[theorem]{Remark}

\newcommand{\R}{\mathbb{R}}
\newcommand{\Z}{\mathbb{Z}}
\newcommand{\N}{\mathbb{N}}
\newcommand{\Pikl}{\Pi^{k}_{\ell}}

\title{Universality of Transfer Functions Among the Accumulation Points of $k$-adic Level Sets}
\author{Aristotle}
\date{\today}

\begin{document}

\begin{abstract}
We study a countable family of subsets of the real line, the \emph{level-$\ell$
base-$k$ sets}
\[
  \Pikl \;=\; \ell\cdot\Z[1/k] \;=\; \left\{\, \frac{\ell\,a}{k^m} : a\in\Z,\ m\in\N \,\right\},
\]
and the family of \emph{transfer functions} --- translations $x\mapsto x+c$ by
elements $c\in\Pikl$. We prove that for every base $k\ge 2$ and level $\ell\ge 1$
the set $\Pikl$ is a dense additive subgroup of $\R$ that is perfect: every real
number, and in particular every element of $\Pikl$, is an accumulation point of
$\Pikl$. Hence the accumulation points lying in $\Pikl$ are exactly its elements.
The transfer functions form a monoid under composition, preserve $\Pikl$, and are
continuous. Our main theorem is a \emph{universality} (transitivity) statement:
for any $k\ge 3$, any $1\le\ell<k$, and any two elements $\alpha,\beta\in\Pikl$,
there is a transfer function $f$ with $f(\alpha)=\beta$. A companion
\emph{rigidity} theorem shows this $f$ is unique --- transfer functions agreeing
at a single point are identical --- so the translation action is simply
transitive on $\Pikl$.
\end{abstract}

\maketitle

\section{Introduction}

A subset $S$ of a metric space is \emph{perfect} if it is closed and every point
of $S$ is an accumulation point of $S$. A slightly weaker and often more useful
notion is \emph{dense-in-itself}: every point of $S$ is an accumulation point of
$S$ (no isolated points), without requiring closedness. Perfect and
dense-in-itself sets are central objects in analysis and topology.

We fix integers $k\ge 2$ (the \emph{base}) and $\ell\ge 1$ (the \emph{level}) and
study
\[
  \Pikl \;=\; \ell\cdot\Z[1/k]
        \;=\; \left\{\, \frac{\ell\,a}{k^m} : a\in\Z,\ m\in\N \,\right\} \subseteq \R,
\]
which we call the \emph{level-$\ell$ base-$k$ set}. We introduce \emph{transfer
functions}: the translations $x\mapsto x+c$ with $c\in\Pikl$. Our results
establish two complementary facts: \emph{universality} (any element of $\Pikl$
can be carried to any other by a transfer function) and \emph{rigidity} (the
transfer function achieving a given assignment is unique). Together they say the
group of transfer functions acts freely and transitively on $\Pikl$, so all
points are equivalent.

\subsection{Notation}
Throughout, $k,\ell\in\N$ with $k\ge 2$, $\ell\ge 1$ unless stated otherwise; the
main theorem uses $k\ge 3$, $1\le\ell<k$. We write $\Z[1/k]=\{a/k^m:a\in\Z,
m\in\N\}$, and $\lfloor x\rfloor$ is the floor of $x$. An \emph{accumulation
point} of a set $S$ is a point $x$ such that every neighbourhood of $x$ contains
a point of $S\setminus\{x\}$.

\section{The level-$\ell$ base-$k$ set}

\begin{definition}[Level set]
For $k,\ell\in\N$ define
\[
  \Pikl = \left\{ x\in\R : \exists\, a\in\Z,\ m\in\N,\ x = \tfrac{\ell\,a}{k^m} \right\}.
\]
\end{definition}

The level $\ell$ is not a mere scaling artifact: for distinct $\ell$ the sets
$\Pikl$ are genuinely different additive subgroups of $\R$.

\begin{lemma}\label{lem:zero}
$0\in\Pikl$.
\end{lemma}
\begin{proof}
Take $a=0$, $m=0$: $\ell\cdot 0/k^0 = 0$.
\end{proof}

\begin{lemma}[Closure under subtraction]\label{lem:sub}
If $k\neq 0$ and $x,y\in\Pikl$ then $x-y\in\Pikl$.
\end{lemma}
\begin{proof}
Write $x=\ell a/k^m$, $y=\ell b/k^n$ with $a,b\in\Z$, $m,n\in\N$. Then
\[
  x-y = \frac{\ell a}{k^m} - \frac{\ell b}{k^n}
      = \frac{\ell\,(a\,k^n - b\,k^m)}{k^{m+n}},
\]
of the required form with integer numerator and exponent $m+n$.
\end{proof}

\begin{lemma}[Closure under addition]\label{lem:add}
If $k\neq 0$ and $x,y\in\Pikl$ then $x+y\in\Pikl$.
\end{lemma}
\begin{proof}
As above, $x+y = \ell(a k^n + b k^m)/k^{m+n}$.
\end{proof}

\begin{corollary}
$(\Pikl,+)$ is an additive subgroup of $(\R,+)$.
\end{corollary}
\begin{proof}
It contains $0$ (Lemma~\ref{lem:zero}), is closed under addition
(Lemma~\ref{lem:add}), and closed under negation since $-y=0-y\in\Pikl$
(Lemma~\ref{lem:sub}).
\end{proof}

\begin{lemma}[Scaling self-similarity]\label{lem:scale}
If $x\in\Pikl$ then $kx\in\Pikl$.
\end{lemma}
\begin{proof}
If $x=\ell a/k^m$ then $kx=\ell(ak)/k^m$.
\end{proof}

\begin{lemma}[Density]\label{lem:dense}
If $k\ge 2$ and $\ell\ge 1$ then $\Pikl$ is dense in $\R$.
\end{lemma}
\begin{proof}
Fix $x\in\R$ and $\varepsilon>0$. Since $k\ge 2$, $k^m\to\infty$, so choose $m$
with $\ell/k^m<\varepsilon$. Let $p=\ell\lfloor xk^m/\ell\rfloor/k^m\in\Pikl$.
Writing $t=xk^m/\ell$, we have $t-1<\lfloor t\rfloor\le t$, so
$0\le x-p=\frac{\ell}{k^m}(t-\lfloor t\rfloor)<\frac{\ell}{k^m}<\varepsilon$.
\end{proof}

\begin{theorem}[Perfectness]\label{thm:perfect}
If $k\ge 2$ and $\ell\ge 1$ then every real number is an accumulation point of
$\Pikl$. In particular every point of $\Pikl$ is an accumulation point of
$\Pikl$; equivalently, the accumulation points that lie in $\Pikl$ are exactly
the elements of $\Pikl$.
\end{theorem}
\begin{proof}
Fix $x\in\R$. By Lemma~\ref{lem:dense}, $x$ lies in the closure of $\Pikl$. Since
$\Pikl$ is dense and $\R$ has no isolated points, $\Pikl\setminus\{x\}$ is still
dense, so $x$ is in the closure of $\Pikl\setminus\{x\}$; that is, $x$ is an
accumulation point of $\Pikl$. Restricting to $x\in\Pikl$ gives the stated
identification.
\end{proof}

\section{Transfer functions}

\begin{definition}[Transfer function]
A function $f:\R\to\R$ is a \emph{transfer function} for $\Pikl$ if there exists
$c\in\Pikl$ with $f(x)=x+c$ for all $x$.
\end{definition}

\begin{lemma}[Invariance]\label{lem:maps}
If $k\neq 0$ and $f$ is a transfer function for $\Pikl$, then
$f(\Pikl)\subseteq\Pikl$.
\end{lemma}
\begin{proof}
Write $f(x)=x+c$, $c\in\Pikl$. For $x\in\Pikl$, Lemma~\ref{lem:add} gives
$x+c\in\Pikl$.
\end{proof}

\begin{lemma}[Identity]
The identity $x\mapsto x$ is a transfer function (take $c=0$).
\end{lemma}

\begin{lemma}[Composition]\label{lem:comp}
If $k\neq 0$ and $f,g$ are transfer functions, so is $f\circ g$.
\end{lemma}
\begin{proof}
If $f(x)=x+c$ and $g(x)=x+d$, then $(f\circ g)(x)=x+(d+c)$ with $d+c\in\Pikl$.
\end{proof}

\begin{corollary}[Group structure]
The transfer functions form a commutative monoid under composition; since
$x\mapsto x+c$ has inverse $x\mapsto x-c$, they form an abelian group isomorphic
to $(\Pikl,+)$ via $c\mapsto(x\mapsto x+c)$.
\end{corollary}

\begin{lemma}[Continuity]
Every transfer function is continuous.
\end{lemma}
\begin{proof}
$x\mapsto x+c$ is the sum of the identity and a constant.
\end{proof}

\section{Main results}

\begin{theorem}[Universality / transitivity]\label{thm:univ}
Let $k\ge 3$ and $1\le\ell<k$. For any $\alpha,\beta\in\Pikl$:
\begin{enumerate}
  \item both $\alpha$ and $\beta$ are accumulation points of $\Pikl$;
  \item there exists a transfer function $f$ with $f(\alpha)=\beta$;
  \item this $f$ maps $\Pikl$ into itself.
\end{enumerate}
\end{theorem}
\begin{proof}
Part (1) is Theorem~\ref{thm:perfect}. For (2), set $c=\beta-\alpha$; by
Lemma~\ref{lem:sub}, $c\in\Pikl$, so $f(x)=x+c$ is a transfer function with
$f(\alpha)=\beta$. Part (3) is Lemma~\ref{lem:maps}.
\end{proof}

\begin{remark}
The analytic content requires only $k\ge 2$ and $\ell\ge 1$. The bound $\ell<k$
is not used; it is retained only to match the range in which the problem was
posed, and $k\ge 3$ can be relaxed to $k\ge 2$.
\end{remark}

\begin{theorem}[Simple transitivity / uniqueness]\label{thm:unique}
If $f,g$ are transfer functions and $f(x_0)=g(x_0)$ for some single $x_0$, then
$f=g$. Consequently the transfer function carrying $\alpha$ to $\beta$ is unique.
\end{theorem}
\begin{proof}
Write $f(x)=x+c$, $g(x)=x+d$. From $x_0+c=x_0+d$ we get $c=d$, so $f=g$. Any $f$
with $f(\alpha)=\beta$ has shift $c=\beta-\alpha$, which is forced.
\end{proof}

\begin{corollary}[Homogeneity]
The group of transfer functions acts freely and transitively on $\Pikl$;
equivalently, $\Pikl$ is a principal homogeneous space for $(\Pikl,+)$, with the
element carrying $\alpha$ to $\beta$ corresponding to $\beta-\alpha$.
\end{corollary}

\section{Algorithmic view}

The proofs are constructive. \textbf{Transfer between two points:} given
$\alpha,\beta\in\Pikl$ as pairs $(a,m)$ with value $\ell a/k^m$, output the shift
$c=\beta-\alpha$ via Lemma~\ref{lem:sub} and normalize.
\textbf{Dense approximation:} given $x\in\R$ and $\varepsilon>0$, choose least
$m$ with $\ell/k^m<\varepsilon$ and return $p=\ell\lfloor xk^m/\ell\rfloor/k^m$;
then $0\le x-p<\varepsilon$. \textbf{Cluster witness:} for $x\in\Pikl$ and
$n\in\N$, the members $x+\ell j/k^m$ ($j=1,\dots,n$, $m$ large) lie in $\Pikl$
and converge to $x$, certifying $x$ as an accumulation point.

\section{Discussion}

The results exhibit a general mechanism: a dense additive subgroup $G$ of a
metric group without isolated points is dense-in-itself, and its translations act
simply transitively on it. The $k$-adic level sets are the concrete, computable
instances, distinguished by the scaling self-similarity of Lemma~\ref{lem:scale}.
Each $\Pikl$ is countable, hence Lebesgue-null and meagre, yet dense and
dense-in-itself: a clean separation of measure/category size from topological
homogeneity.

\section{Future directions}

\begin{enumerate}
  \item \textbf{Richer transfer semigroup.} Enlarge the transfer family to affine
    maps $x\mapsto k^j x + c$ ($j\in\Z$, $c\in\Pikl$), which preserve $\Pikl$ by
    Lemmas~\ref{lem:scale} and~\ref{lem:add}, and study the resulting solvable
    group and its orbits.
  \item \textbf{Group isomorphism packaging.} Package
    Theorem~\ref{thm:unique} as a group isomorphism between the composition group
    of transfer functions and $(\Pikl,+)$.
  \item \textbf{Topological invariants.} Characterize the closure, order type, and
    measure-zero structure of $\Pikl$, and relate the $\ell$-indexed family by
    inclusions and index computations.
  \item \textbf{Toward combinatorial density sets.} Model families of achievable
    hypergraph Tur\'an densities and their accumulation (jump) structure, and
    identify the density-preserving operations playing the role of transfer
    functions there.
  \item \textbf{General perfect subgroups.} Abstract the argument to any dense
    additive subgroup of a metric group without isolated points.
\end{enumerate}

\section{Conclusion}

For every base $k\ge 2$ and level $\ell\ge 1$, the level set
$\Pikl=\ell\cdot\Z[1/k]$ is a dense, dense-in-itself additive subgroup of $\R$
whose accumulation points contained in the set are precisely its own elements.
The transfer functions preserve the set, are continuous, and form a group
isomorphic to $(\Pikl,+)$ that acts simply transitively: any point moves to any
other (universality) by a unique transfer function (rigidity). The level set is a
discrete, measure-zero, yet fully homogeneous space for its natural symmetries.

\end{document}

