from fractions import Fraction
from math import gcd
from typing import Tuple


def in_pi(x: Fraction, k: int, l: int) -> bool:
    """Return True iff x = l*a/k^m for some integer a and m >= 0."""
    if l == 0:
        return x == 0
    denom = (x / l).denominator
    g = gcd(denom, k)
    while g > 1:
        while denom % g == 0:
            denom //= g
        g = gcd(denom, k)
    return denom == 1


def elt(a: int, m: int, k: int, l: int) -> Fraction:
    """The member l*a/k^m of Pi(k, l)."""
    return Fraction(l * a, k ** m)


def check_group(k: int, l: int, samples: Tuple[Tuple[int, int], ...]) -> None:
    """Confirm Pi(k, l) is closed under +, -, and scaling by k."""
    vals = [elt(a, m, k, l) for (a, m) in samples]
    print(f"Pi(k={k}, l={l})")
    for x in vals:
        assert in_pi(x, k, l)
        assert in_pi(k * x, k, l), "scaling by k left the set!"
    for x in vals:
        for y in vals:
            assert in_pi(x + y, k, l), "addition left the set!"
            assert in_pi(x - y, k, l), "subtraction left the set!"
    print(f"  verified closure under +, -, and *k on {len(vals)} members "
          f"({len(vals)**2} pairs).")


if __name__ == "__main__":
    check_group(3, 2, ((5, 2), (-7, 3), (0, 0), (11, 4)))
    check_group(4, 3, ((1, 1), (2, 2), (-3, 0)))
    check_group(5, 2, ((3, 1), (-4, 2), (7, 3)))
    print("All closure checks passed.")

from fractions import Fraction
from math import floor, gcd
from typing import List


def in_pi(x: Fraction, k: int, l: int) -> bool:
    if l == 0:
        return x == 0
    denom = (x / l).denominator
    g = gcd(denom, k)
    while g > 1:
        while denom % g == 0:
            denom //= g
        g = gcd(denom, k)
    return denom == 1


def snap(x: float, k: int, l: int, m: int) -> Fraction:
    """Nearest-below member l*floor(x k^m / l)/k^m of Pi(k, l)."""
    return Fraction(l * floor(x * (k ** m) / l), k ** m)


def approximate(x: float, k: int, l: int, eps: float) -> Fraction:
    """A member of Pi(k, l) within eps of x (density witness)."""
    m = 0
    while l / (k ** m) >= eps:
        m += 1
    return snap(x, k, l, m)


def cluster(x: Fraction, k: int, l: int, n: int) -> List[Fraction]:
    """n distinct members of Pi(k, l) converging to x (accumulation witness)."""
    return [x + Fraction(l, k ** m) for m in range(1, n + 1)]


if __name__ == "__main__":
    import math
    for eps in (1e-2, 1e-4, 1e-8):
        p = approximate(math.pi, 3, 2, eps)
        assert in_pi(p, 3, 2) and abs(math.pi - float(p)) < eps
        print(f"eps={eps:.0e}: pi ~ {float(p):.10f}  (in Pi, error < eps)")
    x = Fraction(3, 4)
    seq = cluster(x, 4, 3, 6)
    assert all(in_pi(s, 4, 3) and s != x for s in seq)
    assert all(abs(seq[i + 1] - x) < abs(seq[i] - x) for i in range(len(seq) - 1))
    print("Converging cluster:", [str(s) for s in seq])
    print("Density and accumulation verified.")

