function DENSE_APPROX(x, k, l, eps):
    m <- 0
    while l / k^m >= eps:
        m <- m + 1
    t <- floor( x * k^m / l )
    return l * t / k^m            # in Pi(k, l), within eps of x

function CLUSTER_WITNESS(x=(a,m0), k, l, n):
    x_val <- l * a / k^m0
    S <- empty list
    for m from m0+1 to m0+n:
        append x_val + l / k^m to S   # in Pi(k,l), != x_val
    return S                          # strictly converges to x_val
